    reg signed [15:0] exp;

    mult_seq dut (.clk(clk), .rst_n(rst_n), .start(start), .a(a), .b(b),
                  .busy(busy), .done(done), .product(product));
    always #5 clk = ~clk;

    initial begin
        #1 rst_n = 0;
        #11 rst_n = 1;
        for (ai = -128; ai < 128; ai = ai + 1) begin
            for (bi = -128; bi < 128; bi = bi + 1) begin
                exp = ai * bi;
                @(negedge clk); start = 1; a = ai; b = bi;
                @(negedge clk); start = 0;
                n = 0;
                while (done !== 1'b1 && n < 20) begin @(negedge clk); n = n + 1; end
                if (done !== 1'b1 || n != 8 || product !== exp) begin
                    $display("FAIL: %0d * %0d = %0d (n=%0d), expected %0d", ai, bi, $signed(product), n, exp);
                    errors = errors + 1;
                end
            end
        end
        if (errors == 0) $display("EXHAUSTIVE TEST PASSED");
        else $display("EXHAUSTIVE TEST FAILED: %0d errors", errors);
        $finish;
    end
endmodule
